  auto qx_nhwc = qx_nchw.contiguous(torch::MemoryFormat::ChannelsLast);
  torch::Tensor X_hat;
  for (auto _ : state)
    X_hat = torch::nn::functional::avg_pool2d(
        qx_nhwc,
        torch::nn::AvgPool2dOptions({4, 4}).ceil_mode(true).count_include_pad(
            true));
}

